/* ===================================================================
   v1.4 letter-to-sound engine.  Replaces the old ad-hoc suffix chain.
   Produces an ASCII respelling which daRespell() maps to Deseret.
   =================================================================== */
// ASCII respelling -> Deseret. Longest-match.
// Vowels: ee ay aa aw oh oo uu ai ow oy ew  i e a u  (o = alias of aa)
// Cons:   ch j th dh sh zh ng  p b t d k g f v s z r l m n h w y
const DA_RESPELL_MAP = [
  ['zh', '\u{10448}'], ['sh', '\u{10447}'], ['ch', '\u{1043D}'],
  ['th', '\u{10443}'], ['dh', '\u{10444}'], ['ng', '\u{1044D}'],
  ['ee', '\u{10428}'], ['ay', '\u{10429}'], ['aa', '\u{1042A}'],
  ['aw', '\u{1042B}'], ['oh', '\u{1042C}'], ['oo', '\u{1042D}'],
  ['uu', '\u{10433}'], ['ai', '\u{10434}'], ['ow', '\u{10435}'],
  ['oy', '\u{1044E}'], ['ew', '\u{1044F}'],
  ['i', '\u{1042E}'], ['e', '\u{1042F}'], ['a', '\u{10430}'],
  ['o', '\u{1042A}'], ['u', '\u{10432}'],
  ['p', '\u{10439}'], ['b', '\u{1043A}'], ['t', '\u{1043B}'],
  ['d', '\u{1043C}'], ['j', '\u{1043E}'], ['k', '\u{1043F}'],
  ['g', '\u{10440}'], ['f', '\u{10441}'], ['v', '\u{10442}'],
  ['s', '\u{10445}'], ['z', '\u{10446}'], ['r', '\u{10449}'],
  ['l', '\u{1044A}'], ['m', '\u{1044B}'], ['n', '\u{1044C}'],
  ['w', '\u{10436}'], ['y', '\u{10437}'], ['h', '\u{10438}'],
];
function daRespell(s) {
  let out = '', i = 0;
  s = String(s);
  while (i < s.length) {
    if (s[i] === '.') { i++; continue; }
    let hit = null;
    for (const [k, v] of DA_RESPELL_MAP) {
      if (s.startsWith(k, i)) { hit = [k, v]; break; }
    }
    if (!hit) throw new Error('bad respelling char "' + s[i] + '" in ' + s);
    out += hit[1]; i += hit[0].length;
  }
  return out;
}
// reverse, for readable diffs


