  if (/[cg]$/.test(stem)) return stem + 'e';                          // charging, managing
  if (/[ei]t$/.test(stem)) return stem;                                // plummeted, marketed, credited
  if (/[^aeiou][aeiou][bcdfklmnprstvz]$/.test(stem)) return stem + 'e'; // skating, hoping
  if (/[aeiou][aeiou][bcdfgklmnprstvz]$/.test(stem)) return stem;     // meeting, waiting
