"below":     "𐐺𐐮𐑊𐐬",
"scarecrow": "𐑅𐐿𐐯𐐲𐐿𐑉𐐬",
"blouses":   "𐐺𐑊𐐵𐑆𐐮𐑆",
"borough":   "𐐺𐐲",
"boroughs":  "𐐺𐐲𐑆",
"cliche":    "𐐿𐑊𐐨𐑇𐐩",
"cliches":   "𐐿𐑊𐐨𐑇𐐩𐑆",
"could":     "𐐿𐐳𐐼",
"gone":      "𐑀𐐫𐑌",
"vetoes":    "𐑂𐐨𐐻𐐬𐑆",
"vetoing":   "𐑂𐐨𐐻𐐬𐐮𐑌𐑀",
"civilian":  "𐑅𐐮𐑂𐐮𐑊𐐷𐐲𐑌",
