"taking":   "𐐻𐐩𐐿𐐮𐑌𐑀",
"baking":   "𐐺𐐩𐐿𐐮𐑌𐑀",
"faking":   "𐑁𐐩𐐿𐐮𐑌𐑀",
"shaking":  "𐑇𐐩𐐿𐐮𐑌𐑀",
"waking":   "𐐶𐐩𐐿𐐮𐑌𐑀",
"skating":  "𐑅𐐿𐐩𐐻𐐮𐑌𐑀",
