// other coronals (Walker 2.2.10): new, due, student, lewd
text = text.replace(/([\u{10449}\u{1043D}\u{1043E}\u{10447}])\u{1044F}/gu, '$1\u{1042D}');
text = text.replace(/([\u{1043B}\u{1043C}\u{1044C}\u{10445}\u{10446}\u{1044A}\u{10443}])\u{1044F}/gu,
'$1\u{1042D}');
